'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var absf = require( '@stdlib/math/base/special/absf' );
var signumf = require( '@stdlib/math/base/special/signumf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// MAIN //

/**
* Computes the Huber loss gradient with respect to a model parameter for a single-precision floating-point number.
*
* @param {number} x - input value
* @param {number} d - threshold
* @param {number} y - true target value
* @param {number} p - predicted value
* @returns {number} Huber loss gradient
*
* @example
* var v = huberGradient( 3.0, 5.0, 10.2, 0.782 );
* // returns -15.0
*
* @example
* var v = huberGradient( 2.5, 2.0, 8.0, 0.202 );
* // returns -5.0
*
* @example
* var v = huberGradient( -1.3, 1.0, 23.2, -0.999 );
* // returns ~1.3
*
* @example
* var v = huberGradient( -2.0, 11.0, -12.2, 0.234 );
* // returns -22.0
*
* @example
* var v = huberGradient( -2.0, 2.0, -21.0, 0.2 );
* // returns -4.0
*
* @example
* var v = huberGradient( -1.3, 9.0, 4.0, -0.9 );
* // returns ~6.37
*/
function huberGradient( x, d, y, p ) {
	var z;
	if ( isnanf( x ) || isnanf( d ) || isnanf( y ) || isnanf( p ) ) {
		return NaN;
	}
	z = f32( f32( y ) - f32( p ) );
	if ( absf( z ) <= f32( d ) ) {
		return f32( -z * f32( x ) );
	}
	return f32( f32( -f32( d ) * signumf( z ) ) * f32( x ) );
}


// EXPORTS //

module.exports = huberGradient;
